// Q-BTC OpenCL host driver. Mirrors qbtc_sha256_miner.cu.
// Exports the same 5 functions as the CUDA version, named qbtc_cl_*.
//
// Environment: QBTC_CL_BLOCKS / QBTC_CL_THREADS tune the launch size,
//              QBTC_CL_INCLUDE_CPU=1 also lists CPU OpenCL devices (default: GPUs only).

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#define CL_TARGET_OPENCL_VERSION 120
#include <CL/cl.h>

#include "qbtc_cl_source.h"   // generated by build.rs: static const char* QBTC_CL_SOURCE = "...";

#define QBTC_MAX_DEV 8

typedef struct {
    uint32_t a11, e11, b11, c11, d11, f11, g11, h11;
    uint32_t mid[2];
    uint32_t mid_rest[6];
    uint32_t nhi;
    uint32_t cmp_hi, cmp_lo;
    uint32_t kw[64];
    uint32_t wc[64];
} QParams;

static const uint32_t HK[64] = {
    0x428a2f98u,0x71374491u,0xb5c0fbcfu,0xe9b5dba5u,0x3956c25bu,0x59f111f1u,0x923f82a4u,0xab1c5ed5u,
    0xd807aa98u,0x12835b01u,0x243185beu,0x550c7dc3u,0x72be5d74u,0x80deb1feu,0x9bdc06a7u,0xc19bf174u,
    0xe49b69c1u,0xefbe4786u,0x0fc19dc6u,0x240ca1ccu,0x2de92c6fu,0x4a7484aau,0x5cb0a9dcu,0x76f988dau,
    0x983e5152u,0xa831c66du,0xb00327c8u,0xbf597fc7u,0xc6e00bf3u,0xd5a79147u,0x06ca6351u,0x14292967u,
    0x27b70a85u,0x2e1b2138u,0x4d2c6dfcu,0x53380d13u,0x650a7354u,0x766a0abbu,0x81c2c92eu,0x92722c85u,
    0xa2bfe8a1u,0xa81a664bu,0xc24b8b70u,0xc76c51a3u,0xd192e819u,0xd6990624u,0xf40e3585u,0x106aa070u,
    0x19a4c116u,0x1e376c08u,0x2748774cu,0x34b0bcb5u,0x391c0cb3u,0x4ed8aa4au,0x5b9cca4fu,0x682e6ff3u,
    0x748f82eeu,0x78a5636fu,0x84c87814u,0x8cc70208u,0x90befffau,0xa4506cebu,0xbef9a3f7u,0xc67178f2u
};
static const uint32_t HINIT[8] = {
    0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,
    0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u
};

#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define CH(e,f,g) (((e)&(f))^(~(e)&(g)))
#define MAJ(a,b,c) (((a)&(b))^((a)&(c))^((b)&(c)))
#define EP0(a) (ROTR(a,2)^ROTR(a,13)^ROTR(a,22))
#define EP1(e) (ROTR(e,6)^ROTR(e,11)^ROTR(e,25))
#define SIG0(x) (ROTR(x,7)^ROTR(x,18)^((x)>>3))
#define SIG1(x) (ROTR(x,17)^ROTR(x,19)^((x)>>10))

#define WVAR_MASK 0xffffffffff540800ULL
#define wvar(i)   (((WVAR_MASK)>>(i))&1ULL)

typedef struct {
    cl_platform_id    platform;
    cl_device_id      device;
    cl_context        ctx;
    cl_command_queue  queue;
    cl_program        prog;
    cl_kernel         kernel;
    cl_mem            d_found;
    cl_mem            d_stop;
    cl_mem            d_kw3;
    cl_mem            d_params;
    int               sm_count;
} ClDev;

static ClDev g_devs[QBTC_MAX_DEV];
static int   g_enumerated = 0;

// --- host_transform: block1 compression + partial round 11 (without nlo) ---
static void host_transform(uint32_t s[8], const uint32_t win[16]) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) w[i] = win[i];
    for (int i = 16; i < 64; i++) w[i] = SIG1(w[i-2]) + w[i-7] + SIG0(w[i-15]) + w[i-16];
    uint32_t a = s[0], b = s[1], c = s[2], d = s[3];
    uint32_t e = s[4], f = s[5], g = s[6], h = s[7];
    for (int i = 0; i < 64; i++) {
        uint32_t t1 = h + EP1(e) + CH(e,f,g) + HK[i] + w[i];
        uint32_t t2 = EP0(a) + MAJ(a,b,c);
        h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
    }
    s[0]+=a; s[1]+=b; s[2]+=c; s[3]+=d; s[4]+=e; s[5]+=f; s[6]+=g; s[7]+=h;
}

static void build_params(QParams* P, const uint32_t hw[30], uint32_t nhi, uint64_t tu64) {
    uint32_t mid[8];
    for (int i = 0; i < 8; i++) mid[i] = HINIT[i];
    host_transform(mid, hw);

    uint32_t w[64];
    int var[64];
    for (int i = 0; i < 64; i++) { w[i] = 0; var[i] = (int)wvar(i); }

    for (int i = 0; i < 10; i++) w[i] = hw[16 + i];
    w[10] = nhi;
    w[11] = 0;
    w[12] = hw[28];
    w[13] = hw[29];
    w[14] = 0x80000000u;
    w[15] = 0;

    memset(P->kw, 0, sizeof(P->kw));
    memset(P->wc, 0, sizeof(P->wc));

    for (int i = 16; i < 64; i++) {
        if (!var[i]) {
            w[i] = SIG1(w[i-2]) + w[i-7] + SIG0(w[i-15]) + w[i-16];
        } else {
            uint32_t x = 0;
            if (!var[i-2])  x += SIG1(w[i-2]);
            if (!var[i-7])  x += w[i-7];
            if (!var[i-15]) x += SIG0(w[i-15]);
            if (!var[i-16]) x += w[i-16];
            P->wc[i] = x;
        }
    }
    for (int i = 12; i < 64; i++) if (!var[i]) P->kw[i] = HK[i] + w[i];

    uint32_t a = mid[0], b = mid[1], c = mid[2], d = mid[3];
    uint32_t e = mid[4], f = mid[5], g = mid[6], h = mid[7];
    for (int i = 0; i < 11; i++) {
        uint32_t t1 = h + EP1(e) + CH(e,f,g) + HK[i] + w[i];
        uint32_t t2 = EP0(a) + MAJ(a,b,c);
        h = g; g = f; f = e; e = d + t1; d = c; c = b; b = a; a = t1 + t2;
    }
    // Round 11 without W11: t1 = T + nlo
    uint32_t T = h + EP1(e) + CH(e,f,g) + HK[11];
    uint32_t t2 = EP0(a) + MAJ(a,b,c);
    P->a11 = T + t2;
    P->e11 = d + T;
    P->b11 = a; P->c11 = b; P->d11 = c;
    P->f11 = e; P->g11 = f; P->h11 = g;
    P->mid[0] = mid[0]; P->mid[1] = mid[1];
    for (int i = 0; i < 6; i++) P->mid_rest[i] = mid[2 + i];
    P->nhi = nhi;
    P->cmp_hi = (uint32_t)(tu64 >> 32);
    P->cmp_lo = (uint32_t)(tu64);
}

// --- enumerate all GPU+CPU devices once, cache into g_devs ---
static int enumerate_once(void) {
    if (g_enumerated) return 0;
    cl_uint np = 0;
    if (clGetPlatformIDs(0, NULL, &np) != CL_SUCCESS || np == 0) return -1;
    cl_platform_id plats[16];
    if (np > 16) np = 16;
    clGetPlatformIDs(np, plats, NULL);

    cl_device_type types = CL_DEVICE_TYPE_GPU;
    if (getenv("QBTC_CL_INCLUDE_CPU")) types |= CL_DEVICE_TYPE_CPU;

    int idx = 0;
    for (cl_uint i = 0; i < np && idx < QBTC_MAX_DEV; i++) {
        cl_uint nd = 0;
        if (clGetDeviceIDs(plats[i], types, 0, NULL, &nd) != CL_SUCCESS) continue;
        cl_device_id devs[16];
        if (nd > 16) nd = 16;
        clGetDeviceIDs(plats[i], types, nd, devs, NULL);
        for (cl_uint j = 0; j < nd && idx < QBTC_MAX_DEV; j++) {
            g_devs[idx].platform = plats[i];
            g_devs[idx].device = devs[j];
            idx++;
        }
    }
    g_enumerated = 1;
    return 0;
}

int qbtc_cl_device_count(int* n) {
    if (!n) return -1;
    if (enumerate_once() != 0) { *n = 0; return -1; }
    int c = 0;
    while (c < QBTC_MAX_DEV && g_devs[c].device) c++;
    if (c == 0) { *n = 0; return -1; }
    *n = c;
    return 0;
}

int qbtc_cl_init_device(int dev) {
    if (dev < 0 || dev >= QBTC_MAX_DEV) return -6;
    if (enumerate_once() != 0) return -1;
    if (!g_devs[dev].device) return -6;

    ClDev* d = &g_devs[dev];
    if (d->ctx) return 0;  // already initialised

    // The kernel publishes its result with a 64-bit atomic compare-exchange.
    char ext[4096];
    ext[0] = 0;
    clGetDeviceInfo(d->device, CL_DEVICE_EXTENSIONS, sizeof(ext) - 1, ext, NULL);
    ext[sizeof(ext) - 1] = 0;
    if (!strstr(ext, "cl_khr_int64_base_atomics")) {
        fprintf(stderr, "[OpenCL] Device %d lacks cl_khr_int64_base_atomics, skipping.\n", dev);
        return -1;
    }

    cl_int err;
    d->ctx = clCreateContext(NULL, 1, &d->device, NULL, NULL, &err);
    if (err != CL_SUCCESS) return -1;

    d->queue = clCreateCommandQueue(d->ctx, d->device, 0, &err);
    if (err != CL_SUCCESS) return -1;

    const char* src = QBTC_CL_SOURCE;
    size_t srclen = strlen(src);
    d->prog = clCreateProgramWithSource(d->ctx, 1, &src, &srclen, &err);
    if (err != CL_SUCCESS) return -1;

    err = clBuildProgram(d->prog, 1, &d->device,
                         "-cl-fast-relaxed-math -cl-mad-enable", NULL, NULL);
    if (err != CL_SUCCESS) {
        size_t loglen = 0;
        clGetProgramBuildInfo(d->prog, d->device, CL_PROGRAM_BUILD_LOG, 0, NULL, &loglen);
        char* log = (char*)malloc(loglen + 1);
        if (log) {
            clGetProgramBuildInfo(d->prog, d->device, CL_PROGRAM_BUILD_LOG, loglen, log, NULL);
            log[loglen] = 0;
            fprintf(stderr, "[OpenCL] Build failed for device %d:\n%s\n", dev, log);
            free(log);
        }
        return -1;
    }

    d->kernel = clCreateKernel(d->prog, "qbtc_mine_kernel", &err);
    if (err != CL_SUCCESS) return -1;

    cl_uint cus = 0;
    clGetDeviceInfo(d->device, CL_DEVICE_MAX_COMPUTE_UNITS, sizeof(cus), &cus, NULL);
    d->sm_count = (int)cus;

    // KW3: block3 message schedule + K
    uint32_t w[64], kw3[64];
    for (int i = 0; i < 15; i++) w[i] = 0;
    w[15] = 0x000003c0u;
    for (int i = 16; i < 64; i++) w[i] = SIG1(w[i-2]) + w[i-7] + SIG0(w[i-15]) + w[i-16];
    for (int i = 0; i < 64; i++) kw3[i] = HK[i] + w[i];

    d->d_kw3 = clCreateBuffer(d->ctx, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR,
                              sizeof(kw3), kw3, &err);
    if (err != CL_SUCCESS) return -1;

    d->d_found  = clCreateBuffer(d->ctx, CL_MEM_READ_WRITE, sizeof(cl_ulong), NULL, &err);
    if (err != CL_SUCCESS) return -1;
    d->d_stop   = clCreateBuffer(d->ctx, CL_MEM_READ_WRITE, sizeof(cl_int),   NULL, &err);
    if (err != CL_SUCCESS) return -1;
    d->d_params = clCreateBuffer(d->ctx, CL_MEM_READ_ONLY,  sizeof(QParams),  NULL, &err);
    if (err != CL_SUCCESS) return -1;

    return 0;
}

const char* qbtc_cl_device_name(int id) {
    static char nm[256];
    if (id < 0 || id >= QBTC_MAX_DEV) return "Unknown";
    if (enumerate_once() != 0 || !g_devs[id].device) return "Unknown";
    size_t n = 0;
    if (clGetDeviceInfo(g_devs[id].device, CL_DEVICE_NAME, sizeof(nm), nm, &n) != CL_SUCCESS)
        return "Unknown";
    nm[255] = 0;
    return nm;
}

int qbtc_cl_mine_on(int dev, const uint8_t* h120, uint64_t tu64,
                    uint64_t start, uint64_t bsz,
                    uint64_t* out, volatile int* sf)
{
    if (dev < 0 || dev >= QBTC_MAX_DEV) return -6;
    if (!g_devs[dev].ctx) return -7;
    ClDev* d = &g_devs[dev];

    uint32_t hw[30];
    for (int i = 0; i < 30; i++) {
        const uint8_t* p = h120 + i * 4;
        hw[i] = ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16)
              | ((uint32_t)p[2] << 8)  | (uint32_t)p[3];
    }

    cl_ulong sen = 0xFFFFFFFFFFFFFFFFULL;
    cl_int   zero = 0;
    cl_int err;
    if (clEnqueueWriteBuffer(d->queue, d->d_found, CL_TRUE, 0, sizeof(sen),  &sen, 0, NULL, NULL) != CL_SUCCESS) return -3;
    if (clEnqueueWriteBuffer(d->queue, d->d_stop,  CL_TRUE, 0, sizeof(zero), &zero,0, NULL, NULL) != CL_SUCCESS) return -4;

    const char* eb = getenv("QBTC_CL_BLOCKS");
    const char* et = getenv("QBTC_CL_THREADS");
    int nb = eb ? atoi(eb) : d->sm_count;
    int nt = et ? atoi(et) : 1024;
    if (nb < 1) nb = 1;

    size_t max_wgs = 1024;
    clGetDeviceInfo(d->device, CL_DEVICE_MAX_WORK_GROUP_SIZE, sizeof(max_wgs), &max_wgs, NULL);
    if (nt < 1) nt = (int)max_wgs;
    if ((size_t)nt > max_wgs) nt = (int)max_wgs;

    uint32_t tot = (uint32_t)nb * (uint32_t)nt;

    uint64_t cur = start, remaining = bsz;
    while (remaining > 0) {
        uint32_t nhi = (uint32_t)(cur >> 32);
        uint32_t slo = (uint32_t)cur;
        uint64_t room = 0x100000000ULL - (uint64_t)slo;
        uint64_t len = remaining < room ? remaining : room;
        if (len > 0x80000000ULL) len = 0x80000000ULL;

        QParams P;
        build_params(&P, hw, nhi, tu64);

        if (clEnqueueWriteBuffer(d->queue, d->d_params, CL_TRUE, 0, sizeof(P), &P, 0, NULL, NULL) != CL_SUCCESS) return -2;

        clSetKernelArg(d->kernel, 0, sizeof(cl_mem), &d->d_params);
        clSetKernelArg(d->kernel, 1, sizeof(cl_uint), &slo);
        cl_uint len32 = (cl_uint)len;
        clSetKernelArg(d->kernel, 2, sizeof(cl_uint), &len32);
        clSetKernelArg(d->kernel, 3, sizeof(cl_uint), &tot);
        clSetKernelArg(d->kernel, 4, sizeof(cl_mem), &d->d_found);
        clSetKernelArg(d->kernel, 5, sizeof(cl_mem), &d->d_stop);
        clSetKernelArg(d->kernel, 6, sizeof(cl_mem), &d->d_kw3);

        size_t gsz = (size_t)tot;
        size_t lsz = (size_t)nt;
        err = clEnqueueNDRangeKernel(d->queue, d->kernel, 1, NULL, &gsz, &lsz, 0, NULL, NULL);
        if (err != CL_SUCCESS) return -1;
        if (clFinish(d->queue) != CL_SUCCESS) return -1;

        cl_ulong res = 0;
        if (clEnqueueReadBuffer(d->queue, d->d_found, CL_TRUE, 0, sizeof(res), &res, 0, NULL, NULL) != CL_SUCCESS) return -5;
        if (res != 0xFFFFFFFFFFFFFFFFULL) { *out = (uint64_t)res; return 0; }

        cur += len;
        remaining -= len;
        if (sf && *sf) break;
    }
    return 1;
}

void qbtc_cl_shutdown(void) {
    for (int i = 0; i < QBTC_MAX_DEV; i++) {
        ClDev* d = &g_devs[i];
        if (d->d_kw3)    { clReleaseMemObject(d->d_kw3);    d->d_kw3 = NULL; }
        if (d->d_found)  { clReleaseMemObject(d->d_found);  d->d_found = NULL; }
        if (d->d_stop)   { clReleaseMemObject(d->d_stop);   d->d_stop = NULL; }
        if (d->d_params) { clReleaseMemObject(d->d_params); d->d_params = NULL; }
        if (d->kernel)   { clReleaseKernel(d->kernel);      d->kernel = NULL; }
        if (d->prog)     { clReleaseProgram(d->prog);       d->prog = NULL; }
        if (d->queue)    { clReleaseCommandQueue(d->queue); d->queue = NULL; }
        if (d->ctx)      { clReleaseContext(d->ctx);        d->ctx = NULL; }
    }
    g_enumerated = 0;
}